CREATE OR REPLACE FUNCTION public.approve_program_product_payment_request(p_request_id uuid, p_comment text, p_client_action_id uuid)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.program_requests%rowtype;
  v_existing public.program_request_admin_events%rowtype;
  v_actor_label text;
  v_comment text:=nullif(btrim(coalesce(p_comment,'')),'');
  v_from_status text;
begin
  if auth.uid() is null or not (public.has_admin_permission('program_requests.write') and public.admin_request_module_boundary(p_request_id)) then
    raise exception 'PROGRAM_REQUEST_WRITE_DENIED' using errcode='42501';
  end if;
  if p_client_action_id is null then raise exception 'CLIENT_ACTION_ID_REQUIRED' using errcode='22023'; end if;
  if v_comment is not null and length(v_comment) not between 3 and 2000 then
    raise exception 'PROGRAM_REQUEST_COMMENT_INVALID' using errcode='22023';
  end if;
  select * into v_existing from public.program_request_admin_events where client_action_id=p_client_action_id;
  if v_existing.id is not null then
    if v_existing.request_id<>p_request_id or v_existing.actor_auth_user_id<>auth.uid() or v_existing.action<>'APPROVE' then
      raise exception 'CLIENT_ACTION_ID_CONFLICT' using errcode='23505';
    end if;
    select * into v_row from public.program_requests where id=p_request_id;
    return v_row;
  end if;
  select * into v_row from public.program_requests where id=p_request_id for update;
  if v_row.id is null or v_row.financial_processing_status is null
     or v_row.program_id='prestamo'
     or v_row.financial_submission_snapshot->>'contract_version'<>'PROGRAM_PRODUCT_PAYMENT_V1' then
    raise exception 'PROGRAM_PRODUCT_PAYMENT_REQUEST_NOT_FOUND' using errcode='P0001';
  end if;
  if v_row.financial_approval_snapshot is not null and v_row.status='approved' and v_row.financial_processing_status='completed' then
    return v_row;
  end if;
  if v_row.status not in('requires_financial_processing','in_review') then
    raise exception 'FINANCIAL_REQUEST_NOT_APPROVABLE' using errcode='P0001';
  end if;
  if not v_row.terms_accepted or nullif(btrim(coalesce(v_row.signature_data,'')),'') is null
     or v_row.terms_version_id is null or jsonb_typeof(v_row.financial_submission_snapshot)<>'object'
     or jsonb_typeof(v_row.financial_submission_snapshot->'financialResult')<>'object'
     or jsonb_typeof(v_row.financial_submission_snapshot->'payment_schedule')<>'object' then
    raise exception 'FINANCIAL_SUBMISSION_CONTRACT_MISMATCH' using errcode='22023';
  end if;
  v_from_status:=v_row.status;
  update public.program_requests set
    status='approved',financial_processing_status='completed',financial_approval_snapshot=
      v_row.financial_submission_snapshot||jsonb_build_object(
        'approval_contract_version','PROGRAM_PRODUCT_PAYMENT_APPROVAL_V1',
        'approved_at',now(),'approved_by',auth.uid(),'comment',v_comment
      ),
    financial_approved_at=now(),financial_approved_by=auth.uid(),updated_at=now()
  where id=v_row.id returning * into v_row;
  select coalesce(nullif(btrim(raw_user_meta_data->>'display_name'),''),
    nullif(btrim(raw_user_meta_data->>'full_name'),''),nullif(btrim(raw_user_meta_data->>'name'),''),
    'Personal autorizado') into v_actor_label from auth.users where id=auth.uid();
  insert into public.program_request_admin_events(
    request_id,actor_auth_user_id,actor_label,action,from_status,to_status,comment,client_action_id
  ) values(v_row.id,auth.uid(),left(v_actor_label,160),'APPROVE',v_from_status,'approved',v_comment,p_client_action_id);
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(auth.uid(),v_row.affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_APPROVED',v_row.id,
    jsonb_build_object('program_item_id',v_row.program_item_id,'processing_status','completed','google_handoff',false));
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.create_first_cirugias_program_catalog_item(p_payload jsonb, p_asset_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=(select auth.uid());
  v_after public.program_catalog_items%rowtype;
  v_id uuid;
  v_program text:=btrim(coalesce(p_payload->>'program_key',''));
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_description text:=nullif(btrim(coalesce(p_payload->>'description','')),'');
  v_category text:=nullif(btrim(coalesce(p_payload->>'category_raw','')),'');
  v_price numeric;v_quote boolean;v_mode text;v_sold boolean;v_enabled boolean;v_sort integer;
  v_link jsonb;v_link_id uuid;v_public_asset_id uuid;v_kept uuid[]:='{}'::uuid[];v_position integer:=0;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then
    raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object'
     or p_asset_links is null or jsonb_typeof(p_asset_links)<>'array' then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_payload) k
    where k not in('program_key','name','description','category_raw','price_cash','requires_quote','commercial_mode','sold','enabled','sort_order')
  ) then
    raise exception 'PROGRAM_CATALOG_FIELD_NOT_EDITABLE' using errcode='22023';
  end if;
  begin
    v_price:=nullif(p_payload->>'price_cash','')::numeric;
    v_quote:=(p_payload->>'requires_quote')::boolean;
    v_mode:=coalesce(nullif(btrim(coalesce(p_payload->>'commercial_mode','')),''),case when v_quote then 'PAYROLL_QUOTE' else 'PAYROLL_FIXED' end);
    v_sold:=case when p_payload ? 'sold' then (p_payload->>'sold')::boolean else false end;
    v_enabled:=(p_payload->>'enabled')::boolean;
    v_sort:=(p_payload->>'sort_order')::integer;
  exception when others then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end;
  if v_quote is null or v_enabled is null or v_sold is null or v_sort is null then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_program<>'cirugias' then raise exception 'PROGRAM_CATALOG_PROGRAM_INVALID' using errcode='22023'; end if;
  if length(v_name) not between 2 and 180 then raise exception 'PROGRAM_CATALOG_NAME_INVALID' using errcode='22023'; end if;
  if length(coalesce(v_description,''))>12000 then raise exception 'PROGRAM_CATALOG_DESCRIPTION_TOO_LONG' using errcode='22023'; end if;
  if length(coalesce(v_category,''))>240 then raise exception 'PROGRAM_CATALOG_CATEGORY_TOO_LONG' using errcode='22023'; end if;
  if v_sort not between 1 and 10000 then raise exception 'PROGRAM_CATALOG_ORDER_INVALID' using errcode='22023'; end if;
  if v_price<0 then raise exception 'PROGRAM_CATALOG_PRICE_INVALID' using errcode='22023'; end if;
  if v_mode not in('PAYROLL_FIXED','PAYROLL_QUOTE','DIRECT_CONTACT') then raise exception 'PROGRAM_CATALOG_MODE_INVALID' using errcode='22023'; end if;
  if (v_mode='PAYROLL_QUOTE')<>v_quote then raise exception 'PROGRAM_CATALOG_MODE_QUOTE_MISMATCH' using errcode='22023'; end if;
  if v_mode='PAYROLL_FIXED' and (v_price is null or v_price<=0) then raise exception 'PROGRAM_CATALOG_PRICE_REQUIRED' using errcode='22023'; end if;
  if jsonb_array_length(p_asset_links)>8 then raise exception 'PROGRAM_CATALOG_IMAGE_LIMIT_EXCEEDED' using errcode='22023'; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('program_catalog_items:cirugias',0));
  if exists(select 1 from public.program_catalog_items where program_key='cirugias') then
    raise exception 'CIRUGIAS_PROGRAM_ALREADY_BOOTSTRAPPED' using errcode='P0001';
  end if;
  insert into public.program_catalog_items(
    program_key,name,description,category_raw,price_cash,requires_quote,commercial_mode,sold,sold_at,sold_by,
    request_mode,legacy_boundary,enabled,sort_order,record_origin,source_sheet,source_row_ordinal,source_snapshot_hash,source_payload
  ) values(
    'cirugias',v_name,v_description,v_category,v_price,v_quote,v_mode,v_sold,
    case when v_sold then now() else null end,case when v_sold then v_actor else null end,
    'supabase',false,v_enabled,v_sort,'ADMIN_PROGRAM_CATALOG',null,null,null,'{}'::jsonb
  ) returning * into v_after;
  v_id:=v_after.id;
  for v_link in select value from jsonb_array_elements(p_asset_links) loop
    v_position:=v_position+1;
    begin
      v_link_id:=nullif(v_link->>'link_id','')::uuid;
      v_public_asset_id:=nullif(v_link->>'public_asset_id','')::uuid;
    exception when others then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end;
    if v_link_id is not null or v_public_asset_id is null then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end if;
    if not exists(
      select 1 from public.app_assets
      where id=v_public_asset_id and status='READY' and storage_bucket='app-assets'
        and storage_path like 'program-products/%'
    ) then
      raise exception 'PROGRAM_CATALOG_PUBLIC_ASSET_INVALID' using errcode='22023';
    end if;
    v_link_id:=extensions.gen_random_uuid();
    insert into public.program_catalog_item_assets(
      id,item_id,public_asset_id,private_asset_id,role,sort_order,source_column,source_column_letter,enabled
    ) values(
      v_link_id,v_id,v_public_asset_id,null,case when v_position=1 then 'cover' else 'gallery' end,
      v_position,'ADMIN_UPLOAD','ADMIN_'||replace(v_link_id::text,'-',''),true
    );
    if v_link_id=any(v_kept) then raise exception 'PROGRAM_CATALOG_ASSET_DUPLICATE' using errcode='22023'; end if;
    v_kept:=array_append(v_kept,v_link_id);
  end loop;
  insert into public.admin_audit_log(actor_auth_user_id,resource,action,target_id,result,details)
  values(v_actor,'program_catalog_items','INSERT',v_id::text,'SUCCESS',jsonb_build_object(
    'program_key','cirugias','before',null,
    'after',jsonb_build_object(
      'name',v_after.name,'price_cash',v_after.price_cash,'requires_quote',v_after.requires_quote,
      'commercial_mode',v_after.commercial_mode,'sold',v_after.sold,'sold_at',v_after.sold_at,
      'sold_by',v_after.sold_by,'enabled',v_after.enabled,'sort_order',v_after.sort_order
    ),'asset_count',v_position,'asset_limit',8,'bootstrap',true,'delta_aware',true
  ));
  return (to_jsonb(v_after)-'source_payload'-'sold_by');
end $function$

CREATE OR REPLACE FUNCTION public.create_validated_program_product_payment_request(p_actor_real_auth_user_id uuid, p_affiliate_id uuid, p_impersonation_session_id uuid, p_program_item_id uuid, p_notes text, p_signature_data text, p_terms_version_id uuid, p_document_ids uuid[], p_idempotency_key uuid, p_down_payment numeric, p_term integer, p_expected_profile_version integer, p_schedule_anchor_date date)
 RETURNS program_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_affiliate public.affiliates%rowtype;
  v_item public.program_catalog_items%rowtype;
  v_ctx public.impersonation_sessions%rowtype;
  v_quote public.program_requests%rowtype;
  v_row public.program_requests%rowtype;
  v_policy public.loan_term_policy%rowtype;
  v_rules jsonb;
  v_rule jsonb;
  v_rule_count integer;
  v_price numeric(14,2);
  v_amount numeric(14,2);
  v_source text;
  v_result jsonb;
  v_schedule jsonb;
  v_process text;
  v_period text;
  v_union_label text;
  v_category_label text;
  v_missing integer;
  v_snapshot jsonb;
  v_business_date date:=(now() at time zone 'America/Hermosillo')::date;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED' using errcode='42501'; end if;
  if p_actor_real_auth_user_id is null or not exists(select 1 from auth.users where id=p_actor_real_auth_user_id) then
    raise exception 'AUTH_ACTOR_REQUIRED' using errcode='42501';
  end if;
  select * into v_affiliate from public.affiliates where id=p_affiliate_id for update;
  if v_affiliate.id is null or v_affiliate.financial_profile_version<>p_expected_profile_version then
    raise exception 'CONDITIONS_CHANGED' using errcode='PT409';
  end if;
  if p_impersonation_session_id is null then
    if v_affiliate.auth_user_id is distinct from p_actor_real_auth_user_id then raise exception 'AFFILIATE_CONTEXT_DENIED' using errcode='42501'; end if;
  else
    select * into v_ctx from public.impersonation_sessions where id=p_impersonation_session_id for share;
    if v_ctx.id is null or v_ctx.actor_real_auth_user_id<>p_actor_real_auth_user_id
       or v_ctx.usuario_contexto_affiliate_id<>p_affiliate_id or v_ctx.ended_at is not null or v_ctx.expires_at<=now()
       or not exists(select 1 from public.admin_assignments a join public.admin_roles r on r.id=a.role_id and r.enabled
         where a.auth_user_id=p_actor_real_auth_user_id and a.enabled) then
      raise exception 'IMPERSONATION_CONTEXT_INVALID' using errcode='42501';
    end if;
  end if;
  select * into v_item from public.program_catalog_items where id=p_program_item_id and enabled and request_mode='supabase' for share;
  if v_item.id is null or v_item.program_key='prestamo' then raise exception 'PROGRAM_PRODUCT_NOT_FINANCEABLE' using errcode='22023'; end if;
  if v_item.requires_quote then
    select * into v_quote from public.program_requests
    where affiliate_id=p_affiliate_id and program_item_id=v_item.id and request_type='quote' and status='approved'
      and quoted_amount>0 and (valid_until is null or valid_until>=v_business_date)
    order by responded_at desc nulls last,created_at desc,id desc limit 1 for share;
    if v_quote.id is null then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_quote.quoted_amount;v_source:='APPROVED_QUOTE';
  else
    if v_item.price_cash is null or v_item.price_cash<=0 then raise exception 'AUTHORIZED_PRODUCT_PRICE_UNAVAILABLE' using errcode='P0001'; end if;
    v_price:=v_item.price_cash;v_source:='PRICE_CASH';
  end if;
  if p_down_payment is null or p_down_payment<0 or p_down_payment>=v_price then raise exception 'DOWN_PAYMENT_OUT_OF_RANGE' using errcode='22023'; end if;
  v_amount:=round(v_price-p_down_payment,2);
  select * into v_policy from public.loan_term_policy where id='primary' and enabled;
  if v_policy.id is null then raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001'; end if;
  select u.label,c.label into v_union_label,v_category_label
  from public.affiliates a
  left join public.segmentation_catalog_entries u on u.catalog_type='union' and u.code=a.financial_union_code and u.enabled
  left join public.segmentation_catalog_entries c on c.catalog_type='employment_category' and c.code=a.financial_employee_category_code and c.enabled
  where a.id=v_affiliate.id;
  if v_union_label is null or v_category_label is null then raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001'; end if;
  v_rules:=public.get_financial_runtime_rules();
  select count(*) into v_rule_count
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end;
  if v_rule_count<>1 then raise exception 'CAJA_CHICA_RULE_NOT_ELIGIBLE' using errcode='P0001'; end if;
  select value into v_rule
  from jsonb_array_elements(v_rules) candidate(value)
  where value->>'program_id'='caja'
    and public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(v_category_label)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(v_union_label)
    and case upper(coalesce(value->>'visibility_mode','AUTO'))
      when 'MOSTRAR' then true when 'OCULTAR' then false
      else value->>'available_on' is null or (value->>'available_on')::date between v_business_date
        and (date_trunc('month',v_business_date)+interval '5 months - 1 day')::date end
  limit 1;
  v_rule:=v_rule||jsonb_build_object('status','AVAILABLE');
  v_result:=public.resolve_suti_loan_quote_contract(
    jsonb_build_array(v_rule),v_union_label,v_category_label,
    v_rule->>'id',v_amount,p_term,jsonb_build_object(
      'source','SUPABASE_LOAN_TERM_POLICY','standardTerms',v_policy.standard_terms,
      'customMinTerm',v_policy.custom_min_term,'customStep',v_policy.custom_step,
      'decisionReference',v_policy.decision_reference
    )
  );
  v_process:=case v_affiliate.financial_employee_category_code
    when 'SUPLENTES_VARIABLES' then '3' when 'JUBILADOS_PENSIONADOS' then 'JUB'
    when 'SUPLENTES_FIJOS' then '1' when 'EVENTUALES' then '1' when 'BASE' then '1'
    else null end;
  if v_process is null then raise exception 'PAYROLL_PROCESS_UNRESOLVED' using errcode='P0001'; end if;
  v_period:=case when v_process='JUB' then 'mensual' else 'quincenal' end;
  v_result:=(v_result||jsonb_build_object('paymentPeriod',v_period,'ratePeriod',v_period,'source','SUPABASE_FINANCIAL_CRITERIA'));
  if p_schedule_anchor_date is distinct from v_business_date then raise exception 'SCHEDULE_ANCHOR_CHANGED' using errcode='PT409'; end if;
  v_schedule:=public.generate_program_product_payment_schedule(
    p_schedule_anchor_date,v_process,(v_result->>'paymentCount')::integer,
    (v_result->>'total')::numeric,(v_result->>'paymentPerPeriod')::numeric
  );
  if p_idempotency_key is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_signature_data,'')),'') is null then raise exception 'SIGNATURE_AND_TERMS_REQUIRED' using errcode='22023'; end if;
  if not exists(select 1 from public.program_terms_versions where id=p_terms_version_id and program_id='prestamo'
    and membership_offering_id is null and published) then raise exception 'TERMS_VERSION_REQUIRED' using errcode='22023'; end if;
  select count(*) into v_missing
  from public.resolve_affiliate_document_requirements('PROGRAM','prestamo',p_affiliate_id) requirement
  where requirement.required and not exists(
    select 1 from public.affiliate_documents d
    left join public.affiliate_files af on af.id=d.affiliate_file_id
    join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id) and pa.status='READY'
    join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
    where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
      and d.document_type_id=requirement.document_type_id and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
      and not exists(select 1 from public.affiliate_documents newer where newer.affiliate_id=d.affiliate_id
        and newer.document_type_id=d.document_type_id and (newer.created_at,newer.id)>(d.created_at,d.id))
  );
  if v_missing>0 then raise exception 'REQUIRED_DOCUMENTS_MISSING' using errcode='22023'; end if;
  v_snapshot:=jsonb_build_object(
    'contract_version','PROGRAM_PRODUCT_PAYMENT_V1','calculation_contract_version','SUTI_LOAN_QUOTE_V1',
    'calendar_contract_version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','affiliate_id',p_affiliate_id,
    'actor_real_auth_user_id',p_actor_real_auth_user_id,'impersonation_session_id',p_impersonation_session_id,
    'profile_version',v_affiliate.financial_profile_version,'product',jsonb_build_object(
      'program_item_id',v_item.id,'program_key',v_item.program_key,'name',v_item.name
    ),'authorized_price',v_price,'price_source',v_source,'quote_request_id',v_quote.id,
    'down_payment',round(p_down_payment,2),'financed_amount',v_amount,'fund_program_id','caja',
    'fund_rule_id',v_rule->>'rule_id','criterion_identity',v_rule->>'criterion_identity',
    'financial_authority','SUPABASE','financial_rules_source_hash',v_rule->>'source_snapshot_hash',
    'financialResult',v_result,'payment_schedule',v_schedule,'terms_version_id',p_terms_version_id,
    'confirmed_at',now()
  );
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null then
    if v_row.actor_real_auth_user_id<>p_actor_real_auth_user_id or v_row.program_item_id<>p_program_item_id
       or v_row.requested_amount<>v_amount or v_row.requested_term<>p_term
       or (v_row.financial_submission_snapshot->>'down_payment')::numeric<>round(p_down_payment,2)
       or v_row.financial_submission_snapshot->>'price_source'<>v_source
       or coalesce(v_row.financial_submission_snapshot->>'quote_request_id','')<>coalesce(v_quote.id::text,'') then
      raise exception 'IDEMPOTENCY_CONTRACT_MISMATCH' using errcode='22023';
    end if;
    return v_row;
  end if;
  insert into public.program_requests(
    actor_real_auth_user_id,affiliate_id,usuario_contexto_affiliate_id,impersonation_session_id,impersonation_reason,
    numero_control,program_id,program_item_id,request_type,status,quantity,notes,signature_data,terms_accepted,
    terms_version_id,source_context,financial_processing_status,idempotency_key,requested_amount,requested_term,
    requested_term_semantics,financial_submission_snapshot
  ) values(
    p_actor_real_auth_user_id,p_affiliate_id,case when v_ctx.id is null then null else p_affiliate_id end,v_ctx.id,v_ctx.reason,
    v_affiliate.numero_control,v_item.program_key,v_item.id,'benefit','requires_financial_processing',1,
    left(nullif(btrim(coalesce(p_notes,'')),''),2000),p_signature_data,true,p_terms_version_id,
    jsonb_build_object('source','sutiapp','flow','PROGRAM_PRODUCT_PAYMENT_V1','price_source',v_source,
      'quote_request_id',v_quote.id,'fund_program_id','caja','assisted',v_ctx.id is not null),
    'pending',p_idempotency_key,v_amount,p_term,v_period,v_snapshot
  ) returning * into v_row;
  insert into public.request_documents(request_id,document_type_id,affiliate_document_id,private_asset_id,asset_sha256,status_at_submission)
  select v_row.id,d.document_type_id,d.id,coalesce(d.private_asset_id,af.private_asset_id),pa.content_sha256,d.status
  from public.affiliate_documents d left join public.affiliate_files af on af.id=d.affiliate_file_id
  join public.private_assets pa on pa.id=coalesce(d.private_asset_id,af.private_asset_id)
  join storage.objects so on so.bucket_id=pa.storage_bucket and so.name=pa.storage_path
  where d.id=any(coalesce(p_document_ids,array[]::uuid[])) and d.affiliate_id=p_affiliate_id
    and d.status in('PENDING_REVIEW','UNDER_REVIEW','VERIFIED')
  on conflict(request_id,document_type_id) do nothing;
  insert into public.sensitive_change_audit(actor_auth_user_id,affiliate_id,resource,action,target_id,metadata)
  values(p_actor_real_auth_user_id,p_affiliate_id,'program_requests','PROGRAM_PRODUCT_PAYMENT_CONFIRMED',v_row.id,
    jsonb_build_object('program_item_id',v_item.id,'price_source',v_source,'quote_request_id',v_quote.id,
      'payment_count',p_term,'payment_period',v_period,'assisted',v_ctx.id is not null));
  return v_row;
exception when unique_violation then
  select * into v_row from public.program_requests where affiliate_id=p_affiliate_id and idempotency_key=p_idempotency_key;
  if v_row.id is not null and v_row.program_item_id=p_program_item_id and v_row.requested_amount=v_amount
     and v_row.requested_term=p_term and (v_row.financial_submission_snapshot->>'down_payment')::numeric=round(p_down_payment,2) then
    return v_row;
  end if;
  raise;
end $function$

CREATE OR REPLACE FUNCTION public.generate_program_product_payment_schedule(p_start_date date, p_process_code text, p_number_of_payments integer, p_total numeric, p_regular_payment numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_process text:=upper(btrim(coalesce(p_process_code,'')));
  v_min_date date;
  v_cursor date;
  v_candidate date;
  v_dates date[]:=array[]::date[];
  v_rows jsonb:='[]'::jsonb;
  v_index integer;
  v_payment numeric(14,2);
  v_paid numeric(14,2):=0;
  v_remaining numeric(14,2);
begin
  if p_start_date is null or v_process not in('1','3','JUB') or p_number_of_payments not between 1 and 240
     or p_total is null or p_total<=0 or p_regular_payment is null or p_regular_payment<=0 then
    raise exception 'PAYMENT_SCHEDULE_INPUT_INVALID' using errcode='22023';
  end if;
  v_min_date:=p_start_date+30;
  v_cursor:=date_trunc('month',v_min_date)::date;
  while cardinality(v_dates)<p_number_of_payments loop
    if v_process='JUB' then
      v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,5);
      if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
    else
      v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,15);
      if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
      if cardinality(v_dates)<p_number_of_payments then
        v_candidate:=make_date(extract(year from v_cursor)::integer,extract(month from v_cursor)::integer,
          case when extract(month from v_cursor)::integer=2 then 28 else 30 end);
        if v_candidate>=v_min_date then v_dates:=array_append(v_dates,v_candidate); end if;
      end if;
    end if;
    v_cursor:=(v_cursor+interval '1 month')::date;
    if v_cursor>p_start_date+interval '30 years' then raise exception 'PAYMENT_SCHEDULE_GENERATION_FAILED'; end if;
  end loop;
  for v_index in 1..p_number_of_payments loop
    v_payment:=case when v_index=p_number_of_payments then round(p_total-v_paid,2) else round(p_regular_payment,2) end;
    if v_payment<=0 then raise exception 'PAYMENT_SCHEDULE_TOTAL_INVALID' using errcode='22023'; end if;
    v_paid:=round(v_paid+v_payment,2);
    v_remaining:=greatest(0,round(p_total-v_paid,2));
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object(
      'number',v_index,'date',v_dates[v_index],'payment',v_payment,'remaining_total',v_remaining,
      'final_payment',v_index=p_number_of_payments
    ));
  end loop;
  if v_paid<>round(p_total,2) then raise exception 'PAYMENT_SCHEDULE_RECONCILIATION_FAILED'; end if;
  return jsonb_build_object(
    'version','PROGRAM_PRODUCT_PAYROLL_CALENDAR_V1','process',v_process,
    'frequency',case when v_process='JUB' then 'mensual' else 'quincenal' end,
    'anchor_date',p_start_date,'minimum_first_payment_date',v_min_date,
    'first_payment_date',v_dates[1],'last_payment_date',v_dates[p_number_of_payments],
    'payment_count',p_number_of_payments,'rows',v_rows,'total',round(p_total,2)
  );
end $function$

CREATE OR REPLACE FUNCTION public.get_financial_runtime_rules()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ declare v_authority public.financial_criteria_authority%rowtype; v_result jsonb;
begin
  if current_user<>'postgres' and coalesce(auth.role(),'')<>'service_role' then raise exception 'FINANCIAL_RUNTIME_RULES_DENIED' using errcode='42501'; end if;
  select * into v_authority from public.financial_criteria_authority where id='primary';
  if v_authority.authority<>'SUPABASE' or v_authority.active_import_batch_id is null then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  v_result:=public.financial_runtime_rules_for_batch(v_authority.active_import_batch_id);
  if jsonb_array_length(v_result)<>146 then raise exception 'FINANCIAL_CRITERIA_NOT_CONFIGURED' using errcode='P0001'; end if;
  return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.resolve_suti_loan_quote_contract_v1_engine(p_eligible_rules jsonb, p_financial_union text, p_financial_employee_category text, p_program_id text, p_amount numeric, p_term integer, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rule jsonb;
  v_match_count integer;
  v_max_amount numeric;
  v_rate_factor numeric;
  v_rate numeric;
  v_payment_count integer;
  v_payment_period text;
  v_custom_min integer;
  v_custom_step integer;
  v_standard_terms integer[];
  v_interest numeric;
  v_fee_per_payment numeric := 15;
  v_fee_total numeric;
  v_total numeric;
  v_payment numeric;
  v_term_options jsonb;
begin
  if jsonb_typeof(p_eligible_rules) <> 'array' or jsonb_array_length(p_eligible_rules) < 1 then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end if;
  if nullif(btrim(p_financial_union),'') is null or nullif(btrim(p_financial_employee_category),'') is null then
    raise exception 'AFFILIATE_FINANCIAL_PROFILE_INCOMPLETE' using errcode='P0001';
  end if;
  if nullif(btrim(p_program_id),'') is null or p_amount is null or p_amount::text='NaN' or p_term is null then
    raise exception 'FINANCIAL_REQUEST_OUT_OF_RANGE' using errcode='22023';
  end if;
  if jsonb_typeof(p_policy) <> 'object'
     or p_policy->>'source' <> 'SUPABASE_LOAN_TERM_POLICY'
     or jsonb_typeof(p_policy->'standardTerms') <> 'array' then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end if;

  begin
    v_custom_min := (p_policy->>'customMinTerm')::integer;
    v_custom_step := (p_policy->>'customStep')::integer;
    select coalesce(array_agg(value::integer order by ordinal),array[]::integer[])
      into v_standard_terms
      from jsonb_array_elements_text(p_policy->'standardTerms') with ordinality as terms(value,ordinal);
  exception when others then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end;
  if v_custom_min <= 0 or v_custom_step <= 0 or cardinality(v_standard_terms) < 1 then
    raise exception 'LOAN_TERM_POLICY_UNAVAILABLE' using errcode='P0001';
  end if;

  select count(*) into v_match_count
  from jsonb_array_elements(p_eligible_rules) as candidate(value)
  where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
    and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
    and value->>'status'='AVAILABLE'
    and value->>'id'=p_program_id;

  if v_match_count > 0 then
    select value into v_rule
    from jsonb_array_elements(p_eligible_rules) as candidate(value)
    where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
      and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
      and value->>'status'='AVAILABLE'
      and value->>'id'=p_program_id
    limit 1;
  else
    select count(*) into v_match_count
    from jsonb_array_elements(p_eligible_rules) as candidate(value)
    where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
      and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
      and value->>'status'='AVAILABLE'
      and value->>'program_id'=p_program_id;
    if v_match_count = 1 then
      select value into v_rule
      from jsonb_array_elements(p_eligible_rules) as candidate(value)
      where public.normalize_suti_financial_key(value->>'category')=public.normalize_suti_financial_key(p_financial_employee_category)
        and public.normalize_suti_financial_key(value->>'union')=public.normalize_suti_financial_key(p_financial_union)
        and value->>'status'='AVAILABLE'
        and value->>'program_id'=p_program_id
      limit 1;
    else
      v_rule := null;
    end if;
  end if;

  if v_rule is null then raise exception 'FINANCIAL_PROGRAM_NOT_ELIGIBLE' using errcode='P0001'; end if;
  if jsonb_typeof(v_rule->'max_amount') <> 'number'
     or jsonb_typeof(v_rule->'rate_factor') <> 'number'
     or jsonb_typeof(v_rule->'rate') <> 'number'
     or jsonb_typeof(v_rule->'payment_count') <> 'number'
     or nullif(btrim(v_rule->>'fund'),'') is null
     or nullif(btrim(v_rule->>'program_id'),'') is null
     or nullif(btrim(v_rule->>'payment_period'),'') is null then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end if;

  begin
    v_max_amount := (v_rule->>'max_amount')::numeric;
    v_rate_factor := (v_rule->>'rate_factor')::numeric;
    v_rate := (v_rule->>'rate')::numeric;
    v_payment_count := (v_rule->>'payment_count')::integer;
    v_payment_period := v_rule->>'payment_period';
  exception when others then
    raise exception 'FINANCIAL_RULES_INVALID' using errcode='22023';
  end;
  if p_amount <= 0 or p_amount > v_max_amount or p_term < v_custom_min or p_term > v_payment_count
     or mod(p_term-v_custom_min,v_custom_step) <> 0 then
    raise exception 'FINANCIAL_REQUEST_OUT_OF_RANGE' using errcode='22023';
  end if;

  -- Exact current contract: positive currency values rounded half-up to cents.
  v_interest := round(p_amount*v_rate_factor*p_term,2);
  v_fee_total := round(v_fee_per_payment*p_term,2);
  v_total := round(p_amount+v_interest+v_fee_total,2);
  v_payment := round(v_total/p_term,2);

  select coalesce(jsonb_agg(jsonb_build_object(
    'term',candidate_term,
    'paymentCount',candidate_term,
    'interest',round(p_amount*v_rate_factor*candidate_term,2),
    'administrativeFeePerPayment',v_fee_per_payment,
    'administrativeFeeTotal',round(v_fee_per_payment*candidate_term,2),
    'total',round(p_amount+round(p_amount*v_rate_factor*candidate_term,2)+round(v_fee_per_payment*candidate_term,2),2),
    'paymentPerPeriod',round(round(p_amount+round(p_amount*v_rate_factor*candidate_term,2)+round(v_fee_per_payment*candidate_term,2),2)/candidate_term,2)
  ) order by ordinal),'[]'::jsonb)
  into v_term_options
  from unnest(v_standard_terms) with ordinality as terms(candidate_term,ordinal)
  where candidate_term >= v_custom_min and candidate_term <= v_payment_count;

  return jsonb_build_object(
    'source','GOOGLE_LEGACY','action','quote','amount',p_amount,
    'paymentCount',p_term,'paymentPeriod',v_payment_period,
    'rate',v_rate,'ratePeriod',v_payment_period,
    'interest',v_interest,'administrativeFeePerPayment',v_fee_per_payment,
    'administrativeFeeTotal',v_fee_total,'total',v_total,
    'paymentPerPeriod',v_payment,'fund',v_rule->>'fund',
    'program',v_rule->>'program_id','maxAmount',v_max_amount,'maxTerm',v_payment_count,
    'termOptions',v_term_options,
    'customTerm',jsonb_build_object('min',v_custom_min,'max',v_payment_count,'step',v_custom_step),
    'eligibility',jsonb_build_object('status','AVAILABLE','eligible',true),
    'administrativeFeeRule','$15 por pago',
    'administrativeFeeVersion','LEGACY_EQUIVALENCE_2026-08-23',
    'criteria',jsonb_build_object('termLabel',v_rule->>'term_label'),
    'resolved_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  );
end $function$

CREATE OR REPLACE FUNCTION public.save_program_catalog_item(p_item_id uuid, p_payload jsonb, p_asset_links jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=(select auth.uid());
  v_before public.program_catalog_items%rowtype;
  v_after public.program_catalog_items%rowtype;
  v_id uuid;
  v_program text:=btrim(coalesce(p_payload->>'program_key',''));
  v_name text:=btrim(coalesce(p_payload->>'name',''));
  v_description text:=nullif(btrim(coalesce(p_payload->>'description','')),'');
  v_category text:=nullif(btrim(coalesce(p_payload->>'category_raw','')),'');
  v_price numeric;
  v_quote boolean;
  v_mode text;
  v_sold boolean;
  v_enabled boolean;
  v_sort integer;
  v_existing_asset_count integer:=0;
  v_requested_asset_count integer:=0;
  v_allowed_asset_count integer:=8;
  v_link jsonb;
  v_link_id uuid;
  v_public_asset_id uuid;
  v_kept uuid[]:='{}'::uuid[];
  v_position integer:=0;
begin
  if v_actor is null or not public.has_admin_permission('program_catalog.write') then
    raise exception 'PROGRAM_CATALOG_WRITE_REQUIRED' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object'
     or p_asset_links is null or jsonb_typeof(p_asset_links)<>'array' then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if exists(
    select 1 from jsonb_object_keys(p_payload) k
    where k not in('program_key','name','description','category_raw','price_cash','requires_quote','commercial_mode','sold','enabled','sort_order')
  ) then
    raise exception 'PROGRAM_CATALOG_FIELD_NOT_EDITABLE' using errcode='22023';
  end if;

  if p_item_id is not null then
    select * into v_before from public.program_catalog_items where id=p_item_id for update;
    if v_before.id is null then raise exception 'PROGRAM_CATALOG_ITEM_NOT_FOUND' using errcode='P0001'; end if;
    select count(*)::integer into v_existing_asset_count
    from public.program_catalog_item_assets where item_id=p_item_id and enabled;
    v_allowed_asset_count:=greatest(8,v_existing_asset_count);
  end if;

  begin
    v_price:=nullif(p_payload->>'price_cash','')::numeric;
    v_quote:=(p_payload->>'requires_quote')::boolean;
    v_enabled:=(p_payload->>'enabled')::boolean;
    v_sort:=(p_payload->>'sort_order')::integer;
    v_mode:=nullif(btrim(coalesce(p_payload->>'commercial_mode','')),'');
    v_sold:=case when p_payload ? 'sold' then (p_payload->>'sold')::boolean
      when v_before.id is not null then v_before.sold else false end;
    v_requested_asset_count:=jsonb_array_length(p_asset_links);
  exception when others then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end;
  if v_quote is null or v_enabled is null or v_sold is null or v_sort is null then
    raise exception 'PROGRAM_CATALOG_PAYLOAD_INVALID' using errcode='22023';
  end if;
  if v_mode is null then
    v_mode:=case when v_before.id is not null then v_before.commercial_mode when v_quote then 'PAYROLL_QUOTE' else 'PAYROLL_FIXED' end;
  end if;

  if length(v_name) not between 2 and 180
     and (v_before.id is null or v_name is distinct from v_before.name) then
    raise exception 'PROGRAM_CATALOG_NAME_INVALID' using errcode='22023';
  end if;
  if length(coalesce(v_description,''))>12000
     and (v_before.id is null or v_description is distinct from v_before.description) then
    raise exception 'PROGRAM_CATALOG_DESCRIPTION_TOO_LONG' using errcode='22023';
  end if;
  if length(coalesce(v_category,''))>240
     and (v_before.id is null or v_category is distinct from v_before.category_raw) then
    raise exception 'PROGRAM_CATALOG_CATEGORY_TOO_LONG' using errcode='22023';
  end if;
  if v_sort not between 1 and 10000
     and (v_before.id is null or v_sort is distinct from v_before.sort_order) then
    raise exception 'PROGRAM_CATALOG_ORDER_INVALID' using errcode='22023';
  end if;
  if v_price<0 and (v_before.id is null or v_price is distinct from v_before.price_cash) then
    raise exception 'PROGRAM_CATALOG_PRICE_INVALID' using errcode='22023';
  end if;
  if v_mode not in('PAYROLL_FIXED','PAYROLL_QUOTE','DIRECT_CONTACT') then
    raise exception 'PROGRAM_CATALOG_MODE_INVALID' using errcode='22023';
  end if;
  if (v_mode='PAYROLL_QUOTE')<>v_quote then
    raise exception 'PROGRAM_CATALOG_MODE_QUOTE_MISMATCH' using errcode='22023';
  end if;
  if v_mode='PAYROLL_FIXED' and (v_price is null or v_price<=0)
     and (
       v_before.id is null
       or v_before.commercial_mode<>'PAYROLL_FIXED'
       or (v_before.price_cash is not null and v_before.price_cash>0)
       or v_price is distinct from v_before.price_cash
     ) then
    raise exception 'PROGRAM_CATALOG_PRICE_REQUIRED' using errcode='22023';
  end if;
  if not exists(select 1 from public.program_catalog_items where program_key=v_program)
     and (v_before.id is null or v_program is distinct from v_before.program_key) then
    raise exception 'PROGRAM_CATALOG_PROGRAM_INVALID' using errcode='22023';
  end if;
  if v_requested_asset_count>v_allowed_asset_count then
    raise exception 'PROGRAM_CATALOG_IMAGE_LIMIT_EXCEEDED' using errcode='22023',
      detail='allowed='||v_allowed_asset_count::text||',requested='||v_requested_asset_count::text;
  end if;

  if p_item_id is null then
    insert into public.program_catalog_items(
      program_key,name,description,category_raw,price_cash,requires_quote,commercial_mode,sold,sold_at,sold_by,
      request_mode,legacy_boundary,enabled,sort_order,record_origin,source_sheet,source_row_ordinal,source_snapshot_hash,source_payload
    ) values(
      v_program,v_name,v_description,v_category,v_price,v_quote,v_mode,v_sold,
      case when v_sold then now() else null end,case when v_sold then v_actor else null end,
      'supabase',false,v_enabled,v_sort,'ADMIN_PROGRAM_CATALOG',null,null,null,'{}'::jsonb
    ) returning * into v_after;
    v_id:=v_after.id;
  else
    update public.program_catalog_items set
      program_key=v_program,name=v_name,description=v_description,category_raw=v_category,
      price_cash=v_price,requires_quote=v_quote,commercial_mode=v_mode,sold=v_sold,
      sold_at=case when v_sold then coalesce(v_before.sold_at,now()) else null end,
      sold_by=case when v_sold then coalesce(v_before.sold_by,v_actor) else null end,
      enabled=v_enabled,sort_order=v_sort
    where id=p_item_id returning * into v_after;
    v_id:=v_after.id;
  end if;

  update public.program_catalog_item_assets set sort_order=sort_order+10000 where item_id=v_id and enabled;
  for v_link in select value from jsonb_array_elements(p_asset_links) loop
    v_position:=v_position+1;
    begin
      v_link_id:=nullif(v_link->>'link_id','')::uuid;
      v_public_asset_id:=nullif(v_link->>'public_asset_id','')::uuid;
    exception when others then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end;
    if (v_link_id is null)=(v_public_asset_id is null) then
      raise exception 'PROGRAM_CATALOG_ASSET_LINK_INVALID' using errcode='22023';
    end if;
    if v_link_id is not null then
      if not exists(select 1 from public.program_catalog_item_assets where id=v_link_id and item_id=v_id) then
        raise exception 'PROGRAM_CATALOG_ASSET_LINK_NOT_FOUND' using errcode='P0001';
      end if;
      update public.program_catalog_item_assets set
        enabled=true,role=case when v_position=1 then 'cover' else 'gallery' end,sort_order=v_position
      where id=v_link_id;
    else
      if not exists(
        select 1 from public.app_assets
        where id=v_public_asset_id and status='READY' and storage_bucket='app-assets'
          and storage_path like 'program-products/%'
      ) then
        raise exception 'PROGRAM_CATALOG_PUBLIC_ASSET_INVALID' using errcode='22023';
      end if;
      select id into v_link_id from public.program_catalog_item_assets
      where item_id=v_id and public_asset_id=v_public_asset_id order by enabled desc limit 1;
      if v_link_id is null then
        v_link_id:=extensions.gen_random_uuid();
        insert into public.program_catalog_item_assets(
          id,item_id,public_asset_id,private_asset_id,role,sort_order,source_column,source_column_letter,enabled
        ) values(
          v_link_id,v_id,v_public_asset_id,null,case when v_position=1 then 'cover' else 'gallery' end,
          v_position,'ADMIN_UPLOAD','ADMIN_'||replace(v_link_id::text,'-',''),true
        );
      else
        update public.program_catalog_item_assets set
          enabled=true,role=case when v_position=1 then 'cover' else 'gallery' end,sort_order=v_position
        where id=v_link_id;
      end if;
    end if;
    if v_link_id=any(v_kept) then
      raise exception 'PROGRAM_CATALOG_ASSET_DUPLICATE' using errcode='22023';
    end if;
    v_kept:=array_append(v_kept,v_link_id);
  end loop;
  update public.program_catalog_item_assets set enabled=false
